#pragma once
// The Barlow font files, compiled into the exe (the .cpp is generated by CMake from
// third_party/fonts/*.ttf, so the game needs no files next to it).

#include <cstddef>
#include <string_view>

namespace t20::ui {

struct EmbeddedFont {
  const unsigned char* data = nullptr;
  size_t size = 0;
};

// By file name without extension, e.g. "Barlow-Regular"; {nullptr, 0} if not embedded
EmbeddedFont embeddedFont(std::string_view face);

}  // namespace t20::ui
